/**
 * Optional custom Worker entry (OpenNext "custom worker" pattern) that adds a scheduled
 * handler for commerce reconciliation. NOT used by wrangler.staging.jsonc or
 * wrangler.production.jsonc: switching `main` to this file and adding `triggers.crons`
 * is a separate cloud change that needs Max Tall's explicit approval (staging first).
 */
import type {ExecutionContext,ScheduledController} from '@cloudflare/workers-types';
// @ts-ignore Generated by `opennextjs-cloudflare build`; resolved by wrangler at deploy time.
import openNextWorker from '../../../.open-next/worker.js';
import type {TallshiftCloudflareEnv} from './env.ts';
import {runCommerceSchedule} from '../orders/schedule.ts';
// @ts-ignore Durable Object classes re-exported unchanged from the generated worker.
export {DOQueueHandler,DOShardedTagCache,BucketCachePurge} from '../../../.open-next/worker.js';

export default {
  fetch: (openNextWorker as {fetch: (...args: unknown[]) => Promise<Response>}).fetch,
  async scheduled(_controller: ScheduledController, env: TallshiftCloudflareEnv, ctx: ExecutionContext) {
    // Counts and error codes only: no tickets, hashes of users, secrets or payloads in logs.
    ctx.waitUntil(runCommerceSchedule(env).then(report => console.log(JSON.stringify({event: 'commerce_schedule', ...report}))).catch(() => console.log(JSON.stringify({event: 'commerce_schedule', state: 'failed'}))));
  },
};
